def count_passing_ways(n: int, m: int) -> int:
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # Initial state: one way to stay in place

    for i in range(n):
        dp[i][1] = 1  # One way to pass to the left starting from the ith student

    for i in range(1, n):
        for j in range(1, m + 1):
            dp[i][j] = (dp[i - 1][j - 1] + dp[(i + 1) % n][j - 1]) % 1000000007

    return max(dp[n - 1])
