import math

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    def format_coefficient(coeff, degree):
        if coeff == 0:
            return ""
        sign = "+" if coeff > 0 else "-"
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree == 1:
            return sign + "x"
        elif abs_coeff == 1 and degree > 1:
            return sign + "x^%d" % degree
        else:
            return sign + "%d*x^%d" % (abs_coeff, degree)

    result = ""
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        term = format_coefficient(coeff, i)
        if term:
            if result and not term.startswith(sign):
                result += " "
            result += term

    return result.strip()
