import collections
from typing import List, Tuple, Union

def string_transformation(A: str, B: str, rules: List[Tuple[str, str]]) -> Union[int, str]:
    if len(A) > len(B):
        return "NO ANSWER!"

    queue = collections.deque([(A, 0)])  # (current_string, step_count)
    visited = {A}

    while queue:
        current_string, step_count = queue.popleft()

        if current_string == B:
            return step_count

        for src, tgt in rules:
            n = len(src)
            if current_string.endswith(src) and current_string[:-n] + tgt not in visited:
                visited.add(current_string[:-n] + tgt)
                queue.append((current_string[:-n] + tgt, step_count + 1))

        if step_count >= 10:
            break

    return "NO ANSWER!"
