def remaining_trees_after_clearing(l, areas):
    total_trees = l  # Initially, all trees are on the road

    for start, end in areas:
        if start > end:
            start, end = end, start  # If start is greater than end, swap them

        remaining_after_area = max(0, total_trees - (end - start + 1))  # Calculate remaining trees after clearing the area
        total_trees = remaining_after_area  # Update the total number of trees

    return total_trees
